/**
 * n8n Code Node
 * Modo recomendado: Run Once for All Items
 *
 * Nos esperados no fluxo:
 * - Read Composition Structure
 * - Read Supplier Base
 *
 * Relacionamento:
 * SupplierBase["Cod Un"] === CompositionStructure["Codigo do componente"]
 *
 * Saida:
 * Cod Simp
 * Descricao
 * Cod Componente
 * Cod Cx
 * Cod Jg
 * Cod Dec
 * Cod Composicao
 * Qtd Cx
 * Qtd Jg
 * Qtd Comp
 */

// ======================================================
// CONFIGURACOES
// ======================================================

const NOME_NO_BASE = 'Read Supplier Base';
const NOME_NO_ESTRUTURA = 'Read Composition Structure';

const INCLUIR_BASE_SEM_ESTRUTURA = true;
const IGNORAR_BASE_SEM_COD_UN = true;


// ======================================================
// FUNCOES UTILITARIAS
// ======================================================

function normalizarValor(valor) {
  if (valor === null || valor === undefined) return '';
  return String(valor).trim();
}

function removerAcentos(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizarChave(valor) {
  return removerAcentos(normalizarValor(valor)).toUpperCase();
}

function normalizarNomeCampo(nome) {
  return removerAcentos(nome)
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function criarMapaCampos(obj) {
  const mapa = {};

  for (const chaveOriginal of Object.keys(obj || {})) {
    const chaveNormalizada = normalizarNomeCampo(chaveOriginal);
    mapa[chaveNormalizada] = chaveOriginal;
  }

  return mapa;
}

function pegarCampo(obj, nomesPossiveis) {
  if (!obj) return '';

  const mapa = criarMapaCampos(obj);

  for (const nome of nomesPossiveis) {
    const nomeNormalizado = normalizarNomeCampo(nome);
    const chaveReal = mapa[nomeNormalizado];

    if (chaveReal !== undefined) {
      return normalizarValor(obj[chaveReal]);
    }
  }

  return '';
}

function criarLinhaSaida(baseRow, estruturaRow, codComponenteFallback = '') {
  const codComponente =
    pegarCampo(baseRow, ['Cod Un']) ||
    pegarCampo(estruturaRow, ['Codigo do componente', 'Código do componente']) ||
    codComponenteFallback;

  return {
    json: {
      'Cod Simp': pegarCampo(baseRow, ['Cod Simp']),
      'Descricao':
        pegarCampo(baseRow, ['Descricao', 'Descrição']) ||
        pegarCampo(estruturaRow, ['Descricao do componente', 'Descrição do componente']),

      'Cod Componente': codComponente,

      'Cod Cx': pegarCampo(baseRow, ['Cod Cx']),
      'Cod Jg': pegarCampo(baseRow, ['Cod Jg']),
      'Cod Dec': pegarCampo(baseRow, ['Cod Dec']),

      'Cod Composicao': pegarCampo(estruturaRow, [
        'Codigo da composicao',
        'Código da composição'
      ]),

      'Qtd Cx': pegarCampo(baseRow, ['Qtde Cx', 'Qtd Cx']),
      'Qtd Jg': pegarCampo(baseRow, ['Qtde Jg', 'Qtd Jg']),

      'Qtd Comp': pegarCampo(estruturaRow, [
        'Quantidade do Componente',
        'Qtd Componente',
        'Qtde Componente'
      ]),
    },
  };
}

function validarCampoExiste(rows, aliases) {
  if (!rows.length) return false;

  for (const row of rows) {
    for (const alias of aliases) {
      const valor = pegarCampo(row, [alias]);

      if (valor !== '') {
        return true;
      }
    }
  }

  const primeiraLinha = rows[0] || {};
  const mapa = criarMapaCampos(primeiraLinha);

  for (const alias of aliases) {
    if (mapa[normalizarNomeCampo(alias)] !== undefined) {
      return true;
    }
  }

  return false;
}


// ======================================================
// LEITURA DOS NOS PELO NOME
// ======================================================

let baseItems = [];
let estruturaItems = [];

try {
  baseItems = $(NOME_NO_BASE).all();
} catch (error) {
  throw new Error(
    `Nao consegui ler o no "${NOME_NO_BASE}". Confira se o nome do no esta exatamente como: ${NOME_NO_BASE}`
  );
}

try {
  estruturaItems = $(NOME_NO_ESTRUTURA).all();
} catch (error) {
  throw new Error(
    `Nao consegui ler o no "${NOME_NO_ESTRUTURA}". Confira se o nome do no esta exatamente como: ${NOME_NO_ESTRUTURA}`
  );
}

const baseRows = baseItems.map(item => item.json || {});
const estruturaRows = estruturaItems.map(item => item.json || {});

if (!baseRows.length) {
  throw new Error(`O no "${NOME_NO_BASE}" nao retornou linhas.`);
}

if (!estruturaRows.length) {
  throw new Error(`O no "${NOME_NO_ESTRUTURA}" nao retornou linhas.`);
}


// ======================================================
// VALIDACAO FLEXIVEL DOS CAMPOS PRINCIPAIS
// ======================================================

const validacoesBase = [
  ['Cod Simp'],
  ['Cod Un'],
  ['Cod Cx'],
  ['Cod Dec'],
  ['Cod Jg'],
  ['Descricao', 'Descrição'],
  ['Qtde Cx', 'Qtd Cx'],
  ['Qtde Jg', 'Qtd Jg'],
];

const validacoesEstrutura = [
  ['Codigo da composicao', 'Código da composição'],
  ['Codigo do componente', 'Código do componente'],
  ['Quantidade do Componente', 'Qtd Componente', 'Qtde Componente'],
];

const camposBaseAusentes = validacoesBase
  .filter(aliases => !validarCampoExiste(baseRows, aliases))
  .map(aliases => aliases.map(removerAcentos).join(' / '));

const camposEstruturaAusentes = validacoesEstrutura
  .filter(aliases => !validarCampoExiste(estruturaRows, aliases))
  .map(aliases => aliases.map(removerAcentos).join(' / '));

if (camposBaseAusentes.length) {
  throw new Error(
    `Campos ausentes na ${NOME_NO_BASE}: ${camposBaseAusentes.join(', ')}`
  );
}

if (camposEstruturaAusentes.length) {
  throw new Error(
    `Campos ausentes na ${NOME_NO_ESTRUTURA}: ${camposEstruturaAusentes.join(', ')}`
  );
}


// ======================================================
// INDICE RELACIONAL DA BASE
// Chave: Cod Un
// ======================================================

const basePorCodUn = new Map();
const codigosBaseUsados = new Set();

const diagnostico = {
  totalBase: baseRows.length,
  totalEstrutura: estruturaRows.length,
  baseSemCodUn: 0,
  estruturaSemCodigoComponente: 0,
  codigosBaseDuplicados: [],
  codigosEstruturaSemBase: new Set(),
  codigosBaseSemEstrutura: new Set(),
};

for (const row of baseRows) {
  const codUn = normalizarChave(pegarCampo(row, ['Cod Un']));

  if (!codUn) {
    diagnostico.baseSemCodUn++;

    if (IGNORAR_BASE_SEM_COD_UN) {
      continue;
    }
  }

  if (!basePorCodUn.has(codUn)) {
    basePorCodUn.set(codUn, []);
  }

  basePorCodUn.get(codUn).push(row);
}

for (const [codUn, rows] of basePorCodUn.entries()) {
  if (codUn && rows.length > 1) {
    diagnostico.codigosBaseDuplicados.push({
      codigo: codUn,
      quantidade: rows.length,
    });
  }
}


// ======================================================
// GERACAO DA SAIDA
// Base principal: Estrutura
// ======================================================

const saida = [];

for (const estruturaRow of estruturaRows) {
  const codComponente = normalizarChave(
    pegarCampo(estruturaRow, ['Codigo do componente', 'Código do componente'])
  );

  if (!codComponente) {
    diagnostico.estruturaSemCodigoComponente++;
    saida.push(criarLinhaSaida(null, estruturaRow));
    continue;
  }

  const basesRelacionadas = basePorCodUn.get(codComponente);

  if (!basesRelacionadas || !basesRelacionadas.length) {
    diagnostico.codigosEstruturaSemBase.add(codComponente);
    saida.push(criarLinhaSaida(null, estruturaRow, codComponente));
    continue;
  }

  codigosBaseUsados.add(codComponente);

  for (const baseRow of basesRelacionadas) {
    saida.push(criarLinhaSaida(baseRow, estruturaRow, codComponente));
  }
}


// ======================================================
// INCLUIR BASE SEM ESTRUTURA
// ======================================================

if (INCLUIR_BASE_SEM_ESTRUTURA) {
  for (const [codUn, rows] of basePorCodUn.entries()) {
    if (!codUn) continue;

    if (!codigosBaseUsados.has(codUn)) {
      diagnostico.codigosBaseSemEstrutura.add(codUn);

      for (const baseRow of rows) {
        saida.push(criarLinhaSaida(baseRow, null, codUn));
      }
    }
  }
}


// ======================================================
// DIAGNOSTICO NO PRIMEIRO ITEM
// ======================================================

if (saida.length > 0) {
  saida[0].json._diagnostico = {
    totalBaseRecebido: diagnostico.totalBase,
    totalEstruturaRecebido: diagnostico.totalEstrutura,
    baseSemCodUnIgnorada: diagnostico.baseSemCodUn,
    estruturaSemCodigoComponente: diagnostico.estruturaSemCodigoComponente,
    totalLinhasGeradas: saida.length,
    totalCodigosEstruturaSemBase: diagnostico.codigosEstruturaSemBase.size,
    totalCodigosBaseSemEstrutura: diagnostico.codigosBaseSemEstrutura.size,
    codigosBaseDuplicados: diagnostico.codigosBaseDuplicados,
  };
}

return saida;
